<?php
/**
 * Plugin Name: NESPORTS3 Updater V42 (Master Dashboard & Section Customizer)
 * Description: Section-by-section and page-by-page Master Control Dashboard for NESPORTS3 Store.
 * Version: 42.0
 * Author: NESports
 */

add_action('init', function() {
    $target_dir = WP_PLUGIN_DIR . '/nesports-pro-store/';
    if (!file_exists($target_dir)) {
        return;
    }

    $files = array(
        'includes/class-nesports-admin.php' => base64_decode(''),
        'includes/helpers.php' => base64_decode(''),
        'templates/page-home.php' => base64_decode(''),
        'templates/header-nesports.php' => base64_decode(''),
        'templates/footer-nesports.php' => base64_decode(''),
        'templates/page-story.php' => base64_decode(''),
        'templates/page-contact.php' => base64_decode(''),
        'templates/sections/section-hero.php' => base64_decode(''),
        'templates/sections/section-trustbar.php' => base64_decode(''),
        'templates/sections/section-categories.php' => base64_decode(''),
        'templates/sections/section-banner.php' => base64_decode(''),
        'templates/sections/section-collections-carousel.php' => base64_decode(''),
        'templates/sections/section-bundles.php' => base64_decode(''),
        'templates/sections/section-clothing.php' => base64_decode(''),
        'templates/sections/section-color.php' => base64_decode(''),

    );

    foreach ($files as $file => $content) {
        $dest = $target_dir . $file;
        $dir = dirname($dest);
        if (!file_exists($dir)) {
            wp_mkdir_p($dir);
        }
        file_put_contents($dest, $content);
    }
}, 1);
